 void waitFor(java.util.function.BooleanSupplier predicate)throws Exception{long until=SystemClock.elapsedRealtime()+20000;while(!predicate.getAsBoolean()&&SystemClock.elapsedRealtime()<until)Thread.sleep(30);assertTrue(step,predicate.getAsBoolean());}
 void launch()throws Exception{step="launch owned tracking";Instrumentation.ActivityMonitor monitor=i.addMonitor(TrackingActivity.class.getName(),null,false);try{i.runOnMainSync(()->c.startActivity(new Intent(c,TrackingActivity.class).putExtra("sensor","sonar").putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)));activity=(TrackingActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}ready();}
 void recreate()throws Exception{TrackingActivity previous=activity;Instrumentation.ActivityMonitor monitor=i.addMonitor(TrackingActivity.class.getName(),null,false);try{i.runOnMainSync(previous::recreate);activity=(TrackingActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}waitFor(previous::isDestroyed);ready();}
 void ready()throws Exception{waitFor(()->{boolean[] value={false};i.runOnMainSync(()->value[0]=activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()&&activity.getWindow().getDecorView().isLaidOut());return value[0];});}
 View find(View root,String text){if(text.equals(root.getContentDescription())||root instanceof TextView&&text.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup)for(int n=0;n<((ViewGroup)root).getChildCount();n++){View found=find(((ViewGroup)root).getChildAt(n),text);if(found!=null)return found;}return null;}
 boolean shown(String text){boolean[] value={false};i.runOnMainSync(()->value[0]=activity!=null&&!activity.isDestroyed()&&find(activity.getWindow().getDecorView(),text)!=null);return value[0];}
 void click(String label)throws Exception{step="single click "+label;ready();waitFor(()->shown(label));i.runOnMainSync(()->{View target=find(activity.getWindow().getDecorView(),label);assertNotNull(label,target);assertTrue(target.isEnabled());Rect rect=new Rect();assertTrue(target.getGlobalVisibleRect(rect));assertEquals(target.getHeight(),rect.height());assertTrue(rect.height()>=Design.dp(c,48));assertTrue(target.performClick());});}
 File folder(){File dir=new File(c.getExternalFilesDir(null),"verification");assertTrue(dir.isDirectory()||dir.mkdirs());return dir;}
 boolean brightRegion(android.graphics.Bitmap bitmap,int top,int bottom){int[] row=new int[bitmap.getWidth()];long bright=0,plum=0,dark=0,total=(long)row.length*(bottom-top);int background=Design.PLUM;for(int y=top;y<bottom;y++){bitmap.getPixels(row,0,row.length,0,y,row.length,1);for(int rgb:row){int red=android.graphics.Color.red(rgb),green=android.graphics.Color.green(rgb),blue=android.graphics.Color.blue(rgb);if(red>180&&green>180&&blue>180)bright++;if(red<20&&green<20&&blue<20)dark++;if(Math.abs(red-android.graphics.Color.red(background))<=12&&Math.abs(green-android.graphics.Color.green(background))<=12&&Math.abs(blue-android.graphics.Color.blue(background))<=12)plum++;}}return bright>=24&&plum*100>=total*60&&dark<=2;}
 boolean brightBars(android.graphics.Bitmap bitmap,int status,int navigation){return bitmap!=null&&status>0&&navigation>0&&status+navigation<bitmap.getHeight()&&brightRegion(bitmap,0,status)&&brightRegion(bitmap,bitmap.getHeight()-navigation,bitmap.getHeight());}
 void renderedMeasurements()throws Exception{
  step="actual measured intervals published to visible graph";
  waitFor(()->{boolean[] value={false};i.runOnMainSync(()->{View root=activity.getWindow().getDecorView();value[0]=find(root,"Measured")!=null&&measuredChart(root);});return value[0];});
 }
 boolean measuredChart(View root){if(root instanceof LiveMovementTimeline chart){LiveMovementTimeline.Data data=chart.rendered();return data!=null&&data.bars.stream().anyMatch(bar->bar.value!=null);}if(root instanceof ViewGroup)for(int n=0;n<((ViewGroup)root).getChildCount();n++)if(measuredChart(((ViewGroup)root).getChildAt(n)))return true;return false;}
 LiveMovementTimeline signalChart(View root){if(root instanceof LiveMovementTimeline)return (LiveMovementTimeline)root;if(root instanceof ViewGroup)for(int n=0;n<((ViewGroup)root).getChildCount();n++){LiveMovementTimeline found=signalChart(((ViewGroup)root).getChildAt(n));if(found!=null)return found;}return null;}
 boolean measuredPixels(android.graphics.Bitmap bitmap,Rect bounds){int count=0,expected=Design.VIOLET;for(int y=bounds.top;y<bounds.bottom;y++)for(int x=bounds.left;x<bounds.right;x++){int rgb=bitmap.getPixel(x,y);if(Math.abs(android.graphics.Color.red(rgb)-android.graphics.Color.red(expected))<=20&&Math.abs(android.graphics.Color.green(rgb)-android.graphics.Color.green(expected))<=20&&Math.abs(android.graphics.Color.blue(rgb)-android.graphics.Color.blue(expected))<=20&&++count>=2)return true;}return false;}
 void mainLayout(){i.runOnMainSync(()->{View root=activity.getWindow().getDecorView();assertTrue(activity.hasWindowFocus());LiveMovementTimeline chart=signalChart(root);assertNotNull(chart);Rect plot=new Rect();assertTrue(chart.getGlobalVisibleRect(plot));assertEquals(chart.getHeight(),plot.height());assertEquals(chart.getWidth(),plot.width());View pause=find(root,"Pause tracking");if(pause==null)pause=find(root,"Resume tracking");assertNotNull(pause);View stop=find(root,"Stop tracking"),more=find(root,"Tracking options");assertNotNull(stop);assertNotNull(more);Rect pauseBounds=new Rect(),stopBounds=new Rect();assertTrue(pause.getGlobalVisibleRect(pauseBounds));assertTrue(stop.getGlobalVisibleRect(stopBounds));
  for(View target:new View[]{pause,stop,more}){assertTrue(target.isEnabled()&&target.isClickable());Rect bounds=new Rect();assertTrue(target.getGlobalVisibleRect(bounds));assertEquals(target.getHeight(),bounds.height());assertEquals(target.getWidth(),bounds.width());assertTrue(bounds.height()>=Design.dp(c,48));assertTrue(bounds.width()>=Design.dp(c,48));int bottom=root.getHeight()-root.getRootWindowInsets().getInsets(WindowInsets.Type.navigationBars()).bottom;assertTrue(bounds.bottom<=bottom);}
  assertTrue("Full chart clears Pause footer",plot.bottom<=pauseBounds.top);assertTrue("Pause and Stop never overlap",pauseBounds.bottom<=stopBounds.top);for(String detail:List.of("Battery reserve state unavailable","Battery-aware sampling does not change contactless capture","Flip pause · Unavailable with contactless tracking","Flip pause settings","Tracking Do Not Disturb","Timed dream cues"))assertNull("Supporting detail belongs to options: "+detail,find(root,detail));
 });}

 void capture(String name,String label)throws Exception{
  step="capture "+name;ready();waitFor(()->shown(label));
  i.runOnMainSync(()->{View target=find(activity.getWindow().getDecorView(),label);assertNotNull(target);target.requestRectangleOnScreen(new Rect(0,0,target.getWidth(),target.getHeight()),true);});ready();
  CountDownLatch frame=new CountDownLatch(1);int[] bars=new int[2];Rect[] plot={null};boolean measured=name.equals("measuring")||name.equals("resumed")||name.equals("whole-night");
  i.runOnMainSync(()->{View root=activity.getWindow().getDecorView();View target=find(root,label);assertNotNull(target);Rect visible=new Rect();assertTrue(target.getGlobalVisibleRect(visible));assertEquals(target.getHeight(),visible.height());WindowInsets insets=root.getRootWindowInsets();assertNotNull(insets);bars[0]=insets.getInsets(WindowInsets.Type.statusBars()).top;bars[1]=insets.getInsets(WindowInsets.Type.navigationBars()).bottom;if(measured){LiveMovementTimeline chart=signalChart(root);assertNotNull(chart);Rect area=new Rect();assertTrue(chart.getGlobalVisibleRect(area));assertEquals(chart.getHeight(),area.height());area.left+=Design.dp(c,30);area.right-=Design.dp(c,6);area.top+=Design.dp(c,8);area.bottom-=Design.dp(c,30);plot[0]=area;chart.invalidate();}root.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);root.invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));
  if(Set.of("measuring","paused","paused-recreated","resumed","missing","whole-night").contains(name))mainLayout();
  // Clock or battery alone cannot conceal dark Wi-Fi/notification glyphs on plum.
  assertTrue("All rendered system glyphs are light on plum",d.wait(new Condition<UiDevice,Boolean>(){public Boolean apply(UiDevice ignored){android.graphics.Bitmap screen=i.getUiAutomation().takeScreenshot();if(screen==null)return false;android.graphics.Bitmap readable=screen;try{if(screen.getConfig()==android.graphics.Bitmap.Config.HARDWARE)readable=screen.copy(android.graphics.Bitmap.Config.ARGB_8888,false);return brightBars(readable,bars[0],bars[1])&&(!measured||measuredPixels(readable,plot[0]));}finally{if(readable!=null&&readable!=screen)readable.recycle();screen.recycle();}}},5000));
  File file=new File(folder(),evidencePrefix+name+".png");assertTrue(d.takeScreenshot(file));android.graphics.Bitmap actual=android.graphics.BitmapFactory.decodeFile(file.getAbsolutePath());try{assertTrue("Saved original has no dark system glyphs on plum",brightBars(actual,bars[0],bars[1]));if(measured)assertTrue("Saved original contains real violet measurement marks",measuredPixels(actual,plot[0]));}finally{if(actual!=null)actual.recycle();}
 }
 void confirmEnd()throws Exception{
  step="focused owned stop confirmation";View[] dialog={null};Rect[] target={null};CountDownLatch frame=new CountDownLatch(1);
  waitFor(()->{boolean[] ready={false};i.runOnMainSync(()->{View activityRoot=activity.getWindow().getDecorView();View focused=null;for(View root:WindowInspector.getGlobalWindowViews())if(root.hasWindowFocus()&&root.isAttachedToWindow()&&root.isLaidOut()&&root.getContext().getPackageName().equals(c.getPackageName())){assertNull("Exactly one focused app window",focused);focused=root;}if(focused==null||focused==activityRoot||find(focused,"End this recording?")==null)return;View button=find(focused,"End & review");if(button==null||!button.isEnabled())return;Rect bounds=new Rect();if(!button.getGlobalVisibleRect(bounds)||bounds.height()!=button.getHeight()||bounds.width()!=button.getWidth())return;assertTrue(bounds.height()>=Design.dp(c,48));assertTrue(bounds.width()>=Design.dp(c,48));int[] screen=new int[2];button.getLocationOnScreen(screen);target[0]=new Rect(screen[0],screen[1],screen[0]+button.getWidth(),screen[1]+button.getHeight());dialog[0]=focused;ready[0]=true;});return ready[0];});
  i.runOnMainSync(()->{assertTrue(dialog[0].hasWindowFocus());assertTrue(dialog[0].isAttachedToWindow());dialog[0].getViewTreeObserver().registerFrameCommitCallback(frame::countDown);dialog[0].invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));assertTrue(d.takeScreenshot(new File(folder(),evidencePrefix+"stop-confirmation.png")));assertTrue("One measured end input dispatched",d.click(target[0].centerX(),target[0].centerY()));waitFor(()->!dialog[0].isAttachedToWindow());
 }
 @Test public void visibleStartPauseRecreateResumeAndExplicitStopSaveActualNight()throws Exception{fixture(()->{
  launch();assertTrue(audio.isEmpty());capture("setup","Start tracking  →");click("Start tracking  →");
  step="actual valid PCM measurement";waitFor(()->night!=null&&night.state().readings.stream().anyMatch(x->x.movement!=null));renderedMeasurements();capture("measuring","Contactless tracking");assertEquals(1,audio.size());
  click("Pause tracking");waitFor(()->night.state().phase.equals("PAUSED"));capture("paused","Resume tracking");assertTrue(audio.get(0).closed);long before=night.state().active;
  click("Tracking options");assertTrue(shown("Battery reserve state unavailable"));assertTrue(shown("Battery-aware sampling does not change contactless capture"));assertTrue(shown("Flip pause · Unavailable with contactless tracking"));assertTrue(shown("Flip pause settings"));assertTrue(shown("Tracking Do Not Disturb"));assertTrue(shown("Timed dream cues"));capture("options","Done");
  View[] stale={null,null};i.runOnMainSync(()->{stale[0]=find(activity.getWindow().getDecorView(),"Flip pause settings");stale[1]=find(activity.getWindow().getDecorView(),"Done");});TrackingActivity oldOptions=activity;
  recreate();capture("options-recreated","Done");assertTrue(oldOptions.isDestroyed());assertEquals("PAUSED",night.state().phase);assertEquals(before,night.state().active);assertEquals(1,audio.size());assertTrue(shown("Flip pause · Unavailable with contactless tracking"));int windows=owned.size();
  i.runOnMainSync(()->{assertFalse(stale[0].isAttachedToWindow());assertFalse(stale[1].isAttachedToWindow());stale[0].performClick();stale[1].performClick();});ready();assertEquals("Detached callbacks create no replacement tracking owner",windows,owned.size());assertTrue(shown("Tracking options"));assertTrue(shown("Done"));
  click("Done");capture("paused-recreated","Resume tracking");assertEquals(before,night.state().active);assertEquals(1,audio.size());TrackingActivity optionsOwner=activity;click("Tracking options");assertTrue(shown("Done"));d.pressBack();waitFor(()->shown("Resume tracking"));assertSame(optionsOwner,activity);assertFalse(activity.isFinishing());assertEquals(before,night.state().active);assertEquals(1,audio.size());clock.advance(250);
  click("Resume tracking");waitFor(()->audio.size()==2&&night.state().readings.stream().anyMatch(x->x.from>before&&x.movement!=null));renderedMeasurements();capture("resumed","Pause tracking");
  audio.get(1).silence=true;waitFor(()->night.state().readings.get(night.state().readings.size()-1).quality==SonarFrame.Quality.NO_ECHO);capture("missing","Signal missing");
  click("Stop tracking");confirmEnd();
  assertTrue(night.awaitClosed(10000));waitFor(()->reviewed&&activity.isDestroyed());assertEquals("",night.state().error);try(Store store=new Store(c,database)){assertEquals(1,store.rows("SELECT * FROM sessions WHERE end IS NOT NULL").size());assertEquals(1,store.rows("SELECT * FROM tracking_pauses WHERE end IS NOT NULL").size());assertFalse(store.rows("SELECT * FROM epochs WHERE signal_quality='VALID'").isEmpty());assertFalse(store.rows("SELECT * FROM epochs WHERE signal_quality='NO_ECHO' AND movement IS NULL").isEmpty());assertTrue(store.rows("SELECT * FROM sound_events").isEmpty());Backup.validate(store.backup());}
  wholeNightTimeline();
 });}
 void wholeNightTimeline()throws Exception{
  step="private eight-hour stored timeline, gaps and real zero";long end=clock.wall(),start=end-8*3600000L,pauseStart=start+4*3600000L,pauseEnd=pauseStart+15*60000L,missingStart=start+2*3600000L,missingEnd=missingStart+30*60000L,durable=end-5000;long id;
  try(Store store=new Store(c,database)){
   id=store.begin(SensorProvenance.SONAR,SensorProvenance.sonar(new SonarConfig(.05f),"UNPROCESSED"));android.database.sqlite.SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{
    db.execSQL("UPDATE sessions SET start=? WHERE id=?",new Object[]{start,id});
    for(long from=start;from<durable;){if(from==pauseStart){store.pause(id,pauseStart);store.resume(id,pauseEnd);from=pauseEnd;continue;}long to=Math.min(durable,from+5000);boolean missing=from>=missingStart&&from<missingEnd;Double movement=missing?null:from<start+15*60000L?0d:.2+Math.floorMod((from-start)/5000,9)*.08;store.sonarCheckpoint(id,from,to,movement,missing?"NO_ECHO":"VALID",missing?0:125,to-start-(from>=pauseEnd?pauseEnd-pauseStart:0));from=to;}
    db.setTransactionSuccessful();
   }finally{db.endTransaction();}
   assertFalse(store.rows("SELECT id FROM epochs WHERE session=? AND movement=0 AND signal_quality='VALID'",""+id).isEmpty());assertFalse(store.rows("SELECT id FROM epochs WHERE session=? AND movement IS NULL AND signal_quality='NO_ECHO'",""+id).isEmpty());assertEquals(1,store.rows("SELECT id FROM tracking_pauses WHERE session=? AND start=? AND end=?",""+id,""+pauseStart,""+pauseEnd).size());
  }
  List<SonarFrame> pending=new ArrayList<>();for(long from=durable-1000;from<end;from+=40)pending.add(new SonarFrame(from-start,Math.min(end,from+40)-start,.4,SonarFrame.Quality.VALID,8,1));
  timelineSnapshot=new TrackingService.Snapshot(new SonarNight.State(.05f,"ACTIVE","Injected private stored night; no device capture","",id,start,end,8*3600000L-(pauseEnd-pauseStart),false,List.copyOf(pending)));
  launch();renderedMeasurements();i.runOnMainSync(()->assertWholeNight(start,end,missingStart,missingEnd,pauseStart,pauseEnd));assertEquals("No additional audio port for a stored graph",2,audio.size());
  timelineReadFailure.set(true);recreate();waitFor(()->shown("Movement history unavailable. Tap to retry."));LiveMovementTimeline[] failed={null};i.runOnMainSync(()->failed[0]=signalChart(activity.getWindow().getDecorView()));assertNotNull(failed[0]);timelineReadFailure.set(false);click("Movement history unavailable. Tap to retry.");renderedMeasurements();i.runOnMainSync(()->assertWholeNight(start,end,missingStart,missingEnd,pauseStart,pauseEnd));capture("whole-night","Contactless tracking");assertTrue(timelineReads.get()>0);assertFalse(TrackingService.running);assertFalse(AlarmService.active);
 }
 void assertWholeNight(long start,long end,long missingStart,long missingEnd,long pauseStart,long pauseEnd){
  LiveMovementTimeline chart=signalChart(activity.getWindow().getDecorView());assertNotNull(chart);LiveMovementTimeline.Data data=chart.rendered();assertNotNull(data);assertEquals(start,data.start);assertEquals(end,data.end);assertEquals("Pause duration changes active counter, never the wall-clock axis",8*3600000L,data.end-data.start);assertTrue(data.bars.size()<=LiveMovementTimeline.MAX_COLUMNS);assertEquals("Valid pending tail is counted once beyond durable data",8*3600000L-(missingEnd-missingStart)-(pauseEnd-pauseStart),data.measuredMillis);Double zero=data.valueAt(start+5*60000L);assertNotNull("Valid zero has a measured column",zero);assertEquals("Measured zero is genuine data",0d,zero,0d);assertNull("Stored missing signal never becomes zero",data.valueAt((missingStart+missingEnd)/2));assertNull("Actual persisted pause remains a gap",data.valueAt((pauseStart+pauseEnd)/2));Double measured=data.valueAt(start+6*3600000L);assertNotNull("Stored valid interval is drawn",measured);assertTrue(measured>0);assertNotNull("Pending current frames fill the real tail",data.valueAt(end-1));assertTrue(chart.getContentDescription().toString().startsWith("Whole-night movement timeline."));
 }
